const body = $input.first().json.query || $input.first().json.body || $input.first().json;
return [{
  json: {
    id_candidato: '0001',
    limite: Number(body.limite || 25),
    origem_execucao: 'cadencia_webhook_brunex',
    referencia: (body.referencia || 'validacao_manual').toString().trim()
  }
}];

return items.map((item) => {
  const nome = (item.json.nome || 'eleitor').toString().trim();
  const tema = (item.json.tema_interesse || 'geral').toString().trim();
  const etapaDestino = item.json.etapa_funil === 'novo_lead' ? 'qualificado' : item.json.etapa_funil || 'engajado';
  const objetivo = etapaDestino === 'qualificado' ? 'qualificar' : 'relacionar';
  return {
    json: {
      ...item.json,
      etapa_destino: etapaDestino,
      objetivo,
      usa_ia: true,
      rotulo_ia: 'Mensagem de cadência gerada para validação operacional.',
      mensagem_final: `Este atendimento é realizado por assistente virtual oficial da campanha.\n\nOlá, ${nome}. A campanha do Brunex registrou seu interesse em ${tema} e mantém este canal aberto para relacionamento e atualização da agenda.`
    }
  };
});

const total = items.length;
return [{
  json: {
    status: 'ok',
    id_candidato: '0001',
    total_processados: total,
    enviados: total,
    message: `Cadência executada para o candidato 0001. ${total} registro(s) processado(s), ${total} pronto(s) para ação.`
  }
}];
